from pathlib import Path
import html
root=Path(__file__).resolve().parents[1]
def contrast(a,b):
 def lum(c):
  v=[int(c[i:i+2],16)/255 for i in (1,3,5)];v=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in v];return sum(x*y for x,y in zip(v,[.2126,.7152,.0722]))
 x,y=sorted([lum(a),lum(b)]);return (y+.05)/(x+.05)
pairs=[('Ink / paper','#171714','#FAF5EB'),('Muted / paper','#5E5E56','#FAF5EB'),('White / terracotta','#FFFFFF','#A94530'),('Terracotta / paper','#A94530','#FAF5EB')]
rows=''.join(f'<tr><td>{n}</td><td>{contrast(a,b):.2f}:1</td><td>Body text approved</td></tr>' for n,a,b in pairs)
css='''
*{box-sizing:border-box}html{background:#e5e2db;color:#171714;font-family:Arial,Helvetica,sans-serif}body{margin:0}.page{width:1120px;min-height:790px;padding:54px 64px 62px;margin:24px auto;background:#faf5eb;position:relative;overflow:hidden;break-after:page}.page:last-child{break-after:auto}.top{display:flex;justify-content:space-between;border-bottom:1px solid #d8d3c8;padding-bottom:15px;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#5e5e56}.foot{position:absolute;bottom:25px;left:64px;right:64px;display:flex;justify-content:space-between;font-size:11px;color:#5e5e56}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:#a94530;margin:30px 0 12px}h1{font:normal 76px/1.02 Georgia,serif;letter-spacing:-3px;margin:0 0 24px}h2{font:normal 44px/1.08 Georgia,serif;letter-spacing:-1.3px;margin:26px 0 18px}h3{font-size:17px;margin:0 0 10px}p{font-size:15px;line-height:1.6;margin:0 0 16px;max-width:760px}.lead{font-size:18px;line-height:1.5;max-width:690px;color:#5e5e56}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.three{grid-template-columns:repeat(3,1fr)}.box{padding:24px;background:#fff;border:1px solid #d8d3c8;border-radius:12px}.dark{background:#171714;color:#faf5eb;border-color:#171714}.art{height:125px;display:flex;align-items:center;justify-content:center;margin-bottom:14px}.art img{width:100%;height:auto;max-height:80px}.caption{font-size:12px;line-height:1.45;color:#5e5e56}.dark .caption{color:#c5c0b5}.rule{border-top:1px solid #d8d3c8;padding-top:14px;margin-top:20px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:12px 9px;border-bottom:1px solid #d8d3c8}th{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#5e5e56}code,pre{font:12px/1.6 Menlo,monospace}code{overflow-wrap:anywhere}pre{padding:20px;background:#171714;color:#faf5eb;border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.swatches{display:flex;gap:12px;margin:24px 0}.swatch{flex:1;min-width:0}.chip{height:95px;border:1px solid #d8d3c8;border-radius:8px;margin-bottom:10px}.swatch strong{display:block;font-size:13px;margin-bottom:6px}.swatch span{font:12px Menlo,monospace}.note{border-left:3px solid #a94530;padding-left:16px;font-size:13px;line-height:1.6;color:#5e5e56;margin:18px 0}.hero-logo{width:100%;margin:58px 0 52px}.cover-bottom{display:grid;grid-template-columns:2fr 1fr;gap:70px;margin-top:42px;border-top:1px solid #d8d3c8;padding-top:24px}.tag{display:inline-block;font-size:11px;letter-spacing:1px;text-transform:uppercase;border:1px solid #d8d3c8;border-radius:20px;padding:7px 12px;margin-right:6px}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:12px 20px;border-radius:8px;border:1px solid transparent;background:#a94530;color:#fff;font-size:14px;font-weight:bold;margin-right:8px}.btn.secondary{background:transparent;border-color:#171714;color:#171714}.browser{border:1px solid #d8d3c8;border-radius:12px;overflow:hidden;background:#fff}.chrome{background:#eee9df;padding:12px 18px;font-size:12px;display:flex;align-items:center;gap:8px}.mock-nav{display:flex;justify-content:space-between;align-items:center;padding:24px 28px;border-bottom:1px solid #d8d3c8;font-size:12px}.mock-nav img{width:245px}.mock-hero{padding:32px 28px;background:#faf5eb}.mock-hero h3{font:normal 43px/1.1 Georgia,serif;letter-spacing:-1px;max-width:550px;margin:12px 0 18px}.tiny{font-size:11px}.icon-row{display:flex;gap:28px;align-items:center;min-height:130px}.app{border-radius:20%;border:1px solid #d8d3c8}.layout-list{display:grid;grid-template-columns:130px 1fr;gap:8px 16px;font-size:14px;line-height:1.5}.layout-list strong{color:#a94530}.number{font:normal 40px Georgia,serif;color:#a94530}.check{font-size:14px;line-height:1.65;margin:0 0 15px}.muted{color:#5e5e56}a{color:#a94530;text-underline-offset:3px}
@page{size:A4 landscape;margin:0}@media print{html{background:white}p{font-size:14px;margin-bottom:12px}.lead{font-size:17px}h2{font-size:40px;margin-top:22px;margin-bottom:16px}.box{padding:20px}.art{height:108px}.hero-logo{margin:42px 0 36px}.cover-bottom{margin-top:30px}td,th{padding:9px}.note{margin:14px 0}.eyebrow{margin-top:24px}.page{width:297mm;height:210mm;min-height:0;margin:0;padding:14mm 17mm 16mm;page-break-inside:avoid}.foot{left:17mm;right:17mm;bottom:7mm}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media screen and (max-width:1150px){.page{width:calc(100% - 24px);min-height:0;padding:32px 24px 70px}.grid,.three,.cover-bottom{grid-template-columns:1fr}.foot{left:24px;right:24px}h1{font-size:58px}.swatches{flex-wrap:wrap}.swatch{flex:1 1 28%}.hero-logo{margin:40px 0}.mock-nav{gap:15px}.mock-nav span{display:none}}
'''
sections=[]
def page(title,body):
 n=len(sections)+1
 sections.append(f'<section class="page"><div class="top"><span>AIssociation / Brand guidelines</span><span>{title}</span></div>{body}<div class="foot"><span>Website identity system · Version 1.0 · 16 November 2026</span><span>{n:02d} / 08</span></div></section>')
page('The identity','''<div class="eyebrow">Connection becomes possibility.</div><h1>A shared identity.<br>A clear direction.</h1><p class="lead">A practical website brand system built around the approved interlocking-band logo.</p><img class="hero-logo" src="assets/logo-ink.svg" alt="AIssociation"><div class="cover-bottom"><div><h3>Thoughtful. Connected. Open.</h3><p>The interlocking bands express exchange and collective progress. Warm neutrals and direct typography give the website a calm, confident foundation.</p></div><div><span class="tag">Digital first</span><span class="tag">v1.0</span><p class="caption" style="margin-top:16px">The logo is approved. Colors, typography and interface examples extend it into a proposed website system.</p></div></div>''')
page('01 / Logo system','''<h2>Give the mark room.</h2><p>Use the full horizontal lockup as the primary signature. Its symbol, spacing and outlined lettering form one fixed composition.</p><div class="grid"><div class="box"><div class="art"><img src="assets/logo-ink.svg" alt="Primary logo"></div><h3>Primary / ink</h3><p class="caption">Preferred on paper, white and quiet light surfaces.</p></div><div class="box dark"><div class="art"><img src="assets/logo-white.svg" alt="Reversed logo"></div><h3>Reversed / white</h3><p class="caption">Use on solid ink surfaces with strong contrast.</p></div></div><div class="grid" style="margin-top:24px"><div><h3>Space and minimum size</h3><p>Let H be the visible height of the complete lockup. Keep at least 0.5H of clear space on every side. Use 240–320 px in desktop headers; never below 220 px.</p><p>For the standalone symbol, keep at least 25% of its width clear. Use 36–44 px in mobile headers. Only the favicon has a dedicated smaller export.</p></div><div><h3>Protect the composition</h3><p>Scale proportionally. Use the supplied SVGs. Do not retype the wordmark, stretch, rotate, add effects, change the internal gap or separate the woven bands.</p><p class="caption">The favicon is intentionally symbol-only. Do not add the wordmark to a browser icon.</p></div></div><div class="note">The SVG master is an outlined reconstruction of the approved raster. For routine production, use these paths rather than generating the logo again.</div>''')
page('02 / Color','''<h2>Warm foundations. Purposeful accent.</h2><p>Use paper and white for most surfaces, ink for hierarchy, and terracotta for primary actions. The accent should guide attention.</p><div class="swatches">'''+''.join(f'<div class="swatch"><div class="chip" style="background:{c}"></div><strong>{n}</strong><span>{c}</span></div>' for n,c in [('Ink','#171714'),('Paper','#FAF5EB'),('White','#FFFFFF'),('Muted','#5E5E56'),('Terracotta','#A94530')])+'''</div><div class="grid"><div><h3>Approved text combinations</h3><table><tr><th>Pair</th><th>Contrast</th><th>Use</th></tr>'''+rows+'''</table><p class="caption" style="margin-top:12px">Ratios calculated from these hex values. All listed pairs exceed 4.5:1. Recheck after changing colors or opacity.</p></div><div><h3>Supporting tokens</h3><p class="caption">Border #D8D3C8 · Focus #285AC7<br>Success #286247 · Error #A32E2E</p><p>Keep status colors functional. Add text or an icon to each message so meaning does not depend on color alone.</p><p>In dark layouts use ink #171714, surface #23231F, text #FAF5EB and muted text #C5C0B5. Use the white logo.</p><p class="caption">Pale borders organize layout; use stronger borders for controls. Dark semantic tokens are opt-in.</p></div></div>''')
page('03 / Typography','''<h2>Clear information. Editorial character.</h2><p>The custom logo remains an image. Use a simple, dependable system stack for website text, with Georgia reserved for expressive editorial headings.</p><div class="grid"><div class="box"><div class="eyebrow" style="margin-top:0">Primary / Arial</div><div style="font-size:36px;font-weight:bold;line-height:1.2;margin:18px 0">Ideas worth<br>building together.</div><p>Arial, Helvetica, sans-serif.<br>Regular 400 · Bold 700</p><p class="caption">Navigation, forms, cards, buttons and everyday content. No external font loading required.</p></div><div class="box"><div class="eyebrow" style="margin-top:0">Editorial / Georgia</div><div style="font:normal 43px/1.12 Georgia,serif;margin:18px 0">A place for<br>what comes next.</div><p>Georgia, Times New Roman, serif.<br>Regular 400</p><p class="caption">Hero headlines and occasional feature titles. Keep interface labels in the primary font.</p></div></div><table style="margin-top:20px"><tr><th>Role</th><th>Desktop / mobile</th><th>Line height</th><th>Weight</th></tr><tr><td>Hero</td><td>64 / 40 px</td><td>1.05–1.15</td><td>400 editorial</td></tr><tr><td>Section / card title</td><td>36 / 28 px · 22 / 20 px</td><td>1.2–1.3</td><td>700 sans</td></tr><tr><td>Body / controls</td><td>16 / 16 px</td><td>1.6 / 1.2</td><td>400 / 700 sans</td></tr><tr><td>Caption / metadata</td><td>13 / 13 px</td><td>1.45</td><td>400 sans</td></tr></table><p class="caption" style="margin-top:12px">Use sentence case, short paragraphs and a reading measure of 60–75 characters. Avoid body copy below 16 px.</p>''')
page('04 / Website expression','''<h2>Make the next step obvious.</h2><div class="browser"><div class="chrome">● ● ● <span style="margin-left:15px">Website direction / illustrative content</span></div><div class="mock-nav"><img src="assets/logo-ink.svg" alt="AIssociation"><span>About &nbsp;&nbsp; Events &nbsp;&nbsp; Community</span><span style="font-weight:bold;color:#a94530">Get involved ↗</span></div><div class="mock-hero"><div class="eyebrow" style="margin-top:0">Learn with others. Build with purpose.</div><h3>Good ideas grow<br>through connection.</h3><p>A community for curious minds, shared learning and useful work.</p><span class="btn">Explore events</span><span class="btn secondary">About the community</span></div></div><div class="grid" style="margin-top:24px"><div><h3>Layout rhythm</h3><p class="caption">1200 px content maximum · 24 px desktop gutters · 16 px mobile gutters. Use a 4 px spacing unit: 8, 12, 16, 24, 32, 48, 64. Cards use 16 px corners; controls use 8 px.</p></div><div><h3>Interaction and access</h3><p class="caption">Aim for at least 44 × 44 px controls. Use visible 3 px focus rings, underlined text links, explicit form labels and written error messages. Keep motion subtle and respect reduced-motion preferences.</p></div></div><div class="note">These are visual examples, not claims about live website features. Keep real screens aligned with the actions the product supports.</div>''')
page('05 / Favicon and app icons','''<h2>A recognizable small signature.</h2><p>The woven symbol stands alone inside a square field. Exported icons use a warm paper background so the mark is clear on light and dark browser chrome.</p><div class="grid"><div class="box"><h3>Browser scale / actual CSS sizes</h3><div class="icon-row"><div><img src="web/icon-16.png" width="16" height="16" alt="16 pixel icon"><p class="caption">16 px</p></div><div><img src="web/icon-32.png" width="32" height="32" alt="32 pixel icon"><p class="caption">32 px</p></div><div><img src="web/icon-48.png" width="48" height="48" alt="48 pixel icon"><p class="caption">48 px</p></div><div><img src="web/apple-touch-icon.png" width="90" height="90" class="app" alt="Apple touch icon"><p class="caption">180 px source</p></div></div><p class="caption">SVG adapts to system color scheme. ICO contains 16, 32 and 48 px images. PNG files supply explicit fallbacks.</p></div><div class="box"><h3>App icon / safe composition</h3><div class="icon-row"><img src="web/icon-512.png" width="110" height="110" class="app" alt="App icon"><img src="web/icon-maskable-512.png" width="110" height="110" style="border-radius:50%" alt="Maskable icon circular crop preview"></div><p class="caption">192 and 512 px standard app icons. Dedicated 512 px maskable icon with extra padding; the artwork stays inside the central safe area.</p></div></div><div class="grid" style="margin-top:24px"><div><h3>Included files</h3><p class="caption">favicon.svg · favicon.ico · favicon.png<br>icon-16/32/48.png · apple-touch-icon.png<br>icon-192/512.png · icon-maskable-512.png<br>site.webmanifest</p></div><div><h3>Use the right source</h3><p class="caption">Do not crop the full wordmark into an icon. Do not add external padding to an already padded icon. Use the standalone transparent symbol for custom avatar layouts.</p></div></div>''')
page('06 / Voice and social','''<h2>Human language. Useful invitations.</h2><div class="grid"><div><h3>Write with clarity</h3><p>Be curious, direct and welcoming. Say what people can do and what they can expect. Explain technical terms when the audience needs them.</p><p><strong>Example:</strong> “Join a workshop. Meet people. Build something useful.”</p><p><strong>Optional brand line:</strong><br>Connect. Learn. Build together.</p><div class="rule"><h3>Images and graphic elements</h3><p class="caption">Use real moments of learning, discussion and making. Keep crops intentional and leave calm areas for text. Abstract graphics may echo the woven geometry sparingly. Avoid robot stock art, decorative neural networks and text over busy images.</p></div></div><div><img src="web/social-card.png" alt="Social preview card" style="width:100%;border:1px solid #d8d3c8;border-radius:10px"><h3 style="margin-top:20px">Social preview / 1200 × 630</h3><p class="caption">Provided as social-card.png. Keep the logo centered and comfortably inset. Add page-specific titles in metadata rather than squeezing long copy into the image.</p><p class="caption">The optional line is an editorial proposal. Use authentic photography with appropriate permission when adding people to public materials.</p></div></div>''')
page('07 / Developer handoff','''<h2>Ready to bring into the website.</h2><div class="grid"><div><div class="check"><span class="number">01</span><br><strong>Copy the kit.</strong> Put web/ and the SVG logo assets in Frontend/public/brand/.</div><div class="check"><span class="number">02</span><br><strong>Replace metadata.</strong> Use head-snippet.html to replace the starter favicon and manifest links. Set the real absolute social image URL.</div><div class="check"><span class="number">03</span><br><strong>Apply the tokens.</strong> Import brand.css after Ionic base CSS. Review component overrides and opt-in dark surfaces.</div></div><div><h3>Minimal image usage</h3><pre>&lt;a href="/" aria-label="AIssociation home"&gt;
  &lt;img src="/brand/logo-ink.svg"
       alt="AIssociation"
       width="280" height="31" /&gt;
&lt;/a&gt;</pre><h3 style="margin-top:24px">Verify before release</h3><p class="caption">Logo on desktop and mobile · 16/32 px favicon · touch icon · keyboard focus · body text contrast · form errors · dark backgrounds · social metadata · manifest paths.</p><p class="caption">Manifest paths assume a root deployment. Merge existing app metadata deliberately. Icons and a manifest do not add offline support.</p></div></div><div class="note">The package contains standalone deliverables and handoff instructions. The current application has not been changed. See README.md for the complete file inventory and integration details.</div><p class="caption">Master files: assets/*.svg · Web package: web/ · Original approval: source/approved-logo.png<br>Keep future revisions versioned. Use the outlined master for exports so the identity stays consistent.</p>''')
(root/'brand-guide.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AIssociation — Website brand guidelines</title><link rel="icon" href="web/favicon.svg" type="image/svg+xml"><style>'+css+'</style></head><body>'+''.join(sections)+'</body></html>')
print('Created eight-page visual guide.');print(rows)
